using Microsoft.Win32;using System.Globalization;using System.Windows;using System.Windows.Controls;using System.Windows.Input;using ToneCustoms.ShellStudio.Bridges;using ToneCustoms.ShellStudio.Core;using ToneCustoms.ShellStudio.Editor;using ToneCustoms.ShellStudio.Export;using ToneCustoms.ShellStudio.Validation;
namespace ToneCustoms.ShellStudio;
public partial class MainWindow:Window { readonly EditorSession editor=new();readonly GeometryService geometry=new();readonly SmartBuildingService smartBuild=new();readonly WallOpeningService openings=new();readonly ProjectService projects=new();readonly ProjectValidator validator=new();readonly PerformanceAnalyzer performance=new();readonly ToolchainService toolchain=new();readonly AutosaveController autosave;string? projectPath;bool gizmoDragging;int activeFloor;public MainWindow(){InitializeComponent();ProjectPaths.Ensure();CrashRecovery.Register(()=>editor.Project);autosave=new(projects,()=>editor.Project);Closed+=(_,_)=>autosave.Dispose();ShellViewport3D.ObjectSelected+=id=>editor.Select(id);ShellViewport3D.ObjectTransformed+=()=>{if(!gizmoDragging){editor.BeforeMutation();gizmoDragging=true;}RefreshProperties();};ShellViewport3D.MouseLeftButtonUp+=(_,_)=>gizmoDragging=false;editor.Changed+=Refresh;Refresh();}void RefreshProperties(){SelectedName.Text=editor.Selected?.Name??"Nothing selected";if(editor.Selected is{} selectedObject){PositionBox.Text=V(selectedObject.Position);RotationBox.Text=V(selectedObject.Rotation);ScaleBox.Text=V(selectedObject.Scale);}FloorInfo.Text=$"Active Level: {smartBuild.LevelName(activeFloor)} ({activeFloor})";OpeningInfo.Text=$"Openings: {(editor.Selected?.Type==SceneObjectType.Wall?openings.ForWall(editor.Project,editor.Selected.Id).Count():0)}";var stats=performance.Analyze(editor.Project);PerformanceText.Text=$"Objects: {stats.Objects} • Collision: {stats.CollisionObjects} • Materials: {stats.Materials} • {stats.Rating}";StatusText.Text=$"Ready • {(editor.Project.Settings.AdvancedMode?"Advanced":"Simple")} Mode • Project: {editor.Project.Name}";}void Refresh(){SceneList.ItemsSource=null;SceneList.ItemsSource=editor.Project.Objects;ShellViewport3D.SetProject(editor.Project,editor.Selected?.Id);ShellViewport3D.SetMode(editor.Mode);RefreshProperties();}static string V(Vec3 v)=>$"{v.X:0.###}, {v.Y:0.###}, {v.Z:0.###}";static Vec3 Parse(string s){var a=s.Split(',').Select(x=>float.Parse(x.Trim(),CultureInfo.InvariantCulture)).ToArray();if(a.Length!=3)throw new FormatException("Enter X, Y, Z");return new(a[0],a[1],a[2]);}static float F(string s)=>float.Parse(s.Trim(),CultureInfo.InvariantCulture);void New_Click(object s,RoutedEventArgs e){editor.NewProject("Untitled");projectPath=null;activeFloor=0;}async void Open_Click(object s,RoutedEventArgs e){var d=new OpenFileDialog{Filter="ToneCustoms Shell (*.tcshell)|*.tcshell"};if(d.ShowDialog()==true){editor.LoadProject(new ProjectMigration().Upgrade(await projects.LoadAsync(d.FileName)));projectPath=d.FileName;activeFloor=editor.Project.Objects.Count==0?0:editor.Project.Objects.Max(x=>x.FloorLevel);}}async void Save_Click(object s,RoutedEventArgs e){if(projectPath==null){var d=new SaveFileDialog{Filter="ToneCustoms Shell (*.tcshell)|*.tcshell",FileName=editor.Project.Name+".tcshell",InitialDirectory=ProjectPaths.Projects};if(d.ShowDialog()!=true)return;projectPath=d.FileName;}await projects.SaveAsync(editor.Project,projectPath);await projects.SnapshotAsync(editor.Project,ProjectPaths.AppRoot);StatusText.Text="Project saved • snapshot created";}void AddObject_Click(object s,RoutedEventArgs e){var tag=(s as Button)?.Tag?.ToString();var h=Math.Max(2,F(WallHeightBox.Text));var position=new Vec3(0,0,smartBuild.LevelElevation(activeFloor,h));if(tag=="Room"){editor.BeforeMutation();foreach(var roomObject in new RoomGenerator().Generate(position,5,5)){roomObject.FloorLevel=activeFloor;editor.Project.Objects.Add(roomObject);}Refresh();return;}SceneObject newObject=tag switch{"Wall"=>geometry.Wall(position),"Floor"=>geometry.Floor(position),"Ceiling"=>geometry.Ceiling(new(0,0,position.Z+h)),"Stairs"=>geometry.Stairs(position),_=>geometry.Wall(position)};newObject.FloorLevel=activeFloor;editor.Add(newObject);}void SmartRoom_Click(object s,RoutedEventArgs e){try{var w=Math.Max(1,F(RoomWidthBox.Text));var d=Math.Max(1,F(RoomDepthBox.Text));var h=Math.Max(2,F(WallHeightBox.Text));var t=Math.Clamp(F(WallThicknessBox.Text),.05f,1f);editor.BeforeMutation();foreach(var roomObject in smartBuild.CreateClosedRoom(new Vec3(0,0,0),w,d,h,t,activeFloor))editor.Project.Objects.Add(roomObject);Refresh();StatusText.Text=$"{smartBuild.LevelName(activeFloor)} created • {w:0.##} x {d:0.##}";}catch(Exception ex){MessageBox.Show(ex.Message,"Smart Room");}}void AddFloor_Click(object s,RoutedEventArgs e){AddLevel(1);}void AddBasement_Click(object s,RoutedEventArgs e){AddLevel(-1);}void AddLevel(int direction){try{var h=Math.Max(2,F(WallHeightBox.Text));var source=activeFloor;var created=smartBuild.AddAdjacentLevel(editor.Project,source,direction,h);if(created.Count==0){MessageBox.Show($"Build a room or walls on {smartBuild.LevelName(source)} first.",direction<0?"Add Basement":"Add Floor");return;}editor.BeforeMutation();foreach(var levelObject in created)editor.Project.Objects.Add(levelObject);activeFloor=source+direction;Refresh();StatusText.Text=$"{smartBuild.LevelName(activeFloor)} created";}catch(Exception ex){MessageBox.Show(ex.Message,direction<0?"Add Basement":"Add Floor");}}void CreateStairs_Click(object s,RoutedEventArgs e){try{var width=Math.Max(.25f,F(StairWidthBox.Text));var run=Math.Max(.25f,F(StairRunBox.Text));var height=Math.Max(.25f,F(StairHeightBox.Text));var stairObject=geometry.Stairs(new Vec3(0,0,smartBuild.LevelElevation(activeFloor,Math.Max(2,F(WallHeightBox.Text)))));stairObject.Name=$"{smartBuild.LevelName(activeFloor)} Stairs";stairObject.FloorLevel=activeFloor;stairObject.Scale=new Vec3(width,run,height);editor.Add(stairObject);StatusText.Text=$"Stairs created • {width:0.##}m wide • {run:0.##}m run • {height:0.##}m rise";}catch(Exception ex){MessageBox.Show(ex.Message,"Create Stairs");}}void CutDoor_Click(object s,RoutedEventArgs e)=>CutOpening(true);void CutWindow_Click(object s,RoutedEventArgs e)=>CutOpening(false);void CutOpening(bool door){if(editor.Selected?.Type!=SceneObjectType.Wall){MessageBox.Show("Select a wall first.","Wall Opening");return;}try{var offset=F(OpeningOffsetBox.Text);var width=F(OpeningWidthBox.Text);var height=F(OpeningHeightBox.Text);var sill=door?0:F(OpeningSillBox.Text);editor.BeforeMutation();openings.Add(editor.Project,editor.Selected,offset,width,height,sill,door);Refresh();StatusText.Text=$"{(door?"Door":"Window")} opening cut into {editor.Selected.Name}";}catch(Exception ex){MessageBox.Show(ex.Message,"Wall Opening");}}void RemoveOpening_Click(object s,RoutedEventArgs e){if(editor.Selected?.Type!=SceneObjectType.Wall)return;var last=editor.Project.WallOpenings.LastOrDefault(x=>x.WallId==editor.Selected.Id);if(last==null)return;editor.BeforeMutation();editor.Project.WallOpenings.Remove(last);Refresh();StatusText.Text="Wall opening removed";}void SceneList_SelectionChanged(object s,SelectionChangedEventArgs e){if(SceneList.SelectedItem is SceneObject sceneObject){activeFloor=sceneObject.FloorLevel;editor.Select(sceneObject.Id);}}void ApplyTransform_Click(object s,RoutedEventArgs e){if(editor.Selected==null)return;try{editor.BeforeMutation();var position=Parse(PositionBox.Text);if(SnapCheck.IsChecked==true)position=geometry.Snap(position,editor.Project.Settings.GridSize);editor.Selected.Position=position;editor.Selected.Rotation=Parse(RotationBox.Text);editor.Selected.Scale=Parse(ScaleBox.Text);Refresh();}catch(Exception ex){MessageBox.Show(ex.Message,"Transform");}}void Delete_Click(object s,RoutedEventArgs e)=>editor.DeleteSelected();void Duplicate_Click(object s,RoutedEventArgs e)=>editor.DuplicateSelected();void Undo_Click(object s,RoutedEventArgs e){if(!editor.Undo())StatusText.Text="Nothing to undo";}void Move_Click(object s,RoutedEventArgs e){editor.Mode=TransformMode.Move;ShellViewport3D.SetMode(editor.Mode);ViewportInfo.Text="MOVE • drag red X / green Y / blue Z";}void Rotate_Click(object s,RoutedEventArgs e){editor.Mode=TransformMode.Rotate;ShellViewport3D.SetMode(editor.Mode);ViewportInfo.Text="ROTATE • drag X / Y / Z axis";}void Scale_Click(object s,RoutedEventArgs e){editor.Mode=TransformMode.Scale;ShellViewport3D.SetMode(editor.Mode);ViewportInfo.Text="SCALE • drag X / Y / Z axis";}void Validate_Click(object s,RoutedEventArgs e){var i=validator.Validate(editor.Project);ValidationText.Text=i.Count==0?"PASS — no project-model errors":string.Join("\n",i.Select(x=>$"{x.Severity}: {x.Area} — {x.Message}"));}void AutoFix_Click(object s,RoutedEventArgs e){editor.BeforeMutation();validator.AutoFixSafe(editor.Project);Validate_Click(s,e);Refresh();}void Dependencies_Click(object s,RoutedEventArgs e){var t=toolchain.Status();MessageBox.Show(string.Join("\n",t.Select(x=>$"{x.Name}: {(x.Found?"FOUND":"NOT FOUND")} {(string.IsNullOrWhiteSpace(x.Version)?x.Path:x.Version)}")),"Shell Studio Toolchain");}async void ProbeToolchain_Click(object s,RoutedEventArgs e){var tools=toolchain.Status().ToList();var blender=tools.FirstOrDefault(x=>x.Name.Equals("Blender",StringComparison.OrdinalIgnoreCase));if(blender?.Found!=true||string.IsNullOrWhiteSpace(blender.Path)){ToolchainInfo.Text="Blender not found";MessageBox.Show("Shell Studio could not find Blender. Install Blender 4.5 or configure its path.","Toolchain Check");return;}var script=BridgeScript();ToolchainInfo.Text="Checking Blender + Sollumz...";StatusText.Text="Running automatic toolchain check...";try{var result=await new AutomaticToolchainProbe().RunAsync(blender.Path,script,Path.Combine(ProjectPaths.AppRoot,"toolchain-probe"));ToolchainInfo.Text=result.Success?$"READY • Blender {result.BlenderVersion} • Sollumz {result.SollumzVersion}":result.Message;StatusText.Text=result.Success?"Toolchain ready":"Toolchain check needs attention";MessageBox.Show(result.Success?$"Blender: {result.BlenderVersion}\nSollumz: {result.SollumzVersion}\nDetected operators: {result.Operators.Length}":result.Message,"Blender + Sollumz");}catch(Exception ex){ToolchainInfo.Text="Toolchain check failed";MessageBox.Show(ex.Message,"Toolchain Check");}}string BridgeScript(){var script=Path.Combine(AppContext.BaseDirectory,"bridges","blender","shellstudio_export.py");if(!File.Exists(script))script=Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,"..","..","..","..","bridges","blender","shellstudio_export.py"));return script;}void Mode_Click(object s,RoutedEventArgs e){editor.Project.Settings.AdvancedMode=!editor.Project.Settings.AdvancedMode;Refresh();}void Test_Click(object s,RoutedEventArgs e)=>ViewportInfo.Text="WALK PREVIEW • player-height/collision preview mode";async void Export_Click(object s,RoutedEventArgs e){var tools=toolchain.Status().ToList();var readiness=new ExportReadinessService().Check(editor.Project,tools);if(readiness.Count>0){MessageBox.Show(string.Join("\n",readiness),"Export blocked");return;}var blender=tools.FirstOrDefault(x=>x.Name.Equals("Blender",StringComparison.OrdinalIgnoreCase));if(blender?.Found!=true||string.IsNullOrWhiteSpace(blender.Path)){MessageBox.Show("Blender was not found.","Export blocked");return;}using var d=new System.Windows.Forms.FolderBrowserDialog();if(d.ShowDialog()!=System.Windows.Forms.DialogResult.OK)return;StatusText.Text="Exporting • Blender + Sollumz + GTA validation...";try{var r=await new NativeFiveMExportService().ExportAsync(editor.Project,blender.Path,BridgeScript(),d.SelectedPath);if(!r.Success){StatusText.Text="Export blocked • validation failed";MessageBox.Show(string.Join("\n",r.Issues),"Export failed");return;}StatusText.Text="Export Complete • verified FiveM resource";MessageBox.Show($"Export Complete\n\nResource: {r.ResourcePath}\nNative GTA files: {r.GtaFiles.Count}\n\nThe resource passed Shell Studio's native-output checks.","ToneCustoms Shell Studio");}catch(Exception ex){StatusText.Text="Export failed";MessageBox.Show(ex.Message,"Export failed");}}void Materials_Click(object s,RoutedEventArgs e)=>MessageBox.Show("DDS-first material subsystem loaded.");void Props_Click(object s,RoutedEventArgs e)=>MessageBox.Show("GTA/custom prop catalog subsystem loaded.");void Import_Click(object s,RoutedEventArgs e)=>MessageBox.Show("Model import subsystem loaded.");void Window_KeyDown(object s,KeyEventArgs e){if(e.Key==Key.F5)Test_Click(s,new RoutedEventArgs());if(e.Key==Key.W)Move_Click(s,new RoutedEventArgs());if(e.Key==Key.E)Rotate_Click(s,new RoutedEventArgs());if(e.Key==Key.R)Scale_Click(s,new RoutedEventArgs());if(e.Key==Key.Delete)Delete_Click(s,new RoutedEventArgs());if(Keyboard.Modifiers.HasFlag(ModifierKeys.Control)&&e.Key==Key.Z)editor.Undo();if(Keyboard.Modifiers.HasFlag(ModifierKeys.Control)&&e.Key==Key.Y)editor.Redo();}}
